  singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),
  import_enabled boolean NOT NULL DEFAULT false
);
INSERT INTO app.curated_template_rollout(singleton,import_enabled) VALUES(true,false);
ALTER TABLE app.curated_template_rollout OWNER TO {{owner_role}};
REVOKE ALL ON app.curated_template_rollout FROM PUBLIC,{{api_runtime_role}},
  {{worker_runtime_role}},{{dispatcher_role}},{{maintenance_role}},{{operator_role}},{{lifecycle_command_role}};
