GRANT SELECT,UPDATE(singleton) ON app.curated_template_rollout TO {{api_runtime_role}};

CREATE TABLE app.curated_template_descriptors (
  template_id text NOT NULL CHECK(template_id ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND octet_length(template_id) BETWEEN 1 AND 64),
  template_version integer NOT NULL CHECK(template_version>0),
  schema_version integer NOT NULL CHECK(schema_version=1),
  base_manifest text NOT NULL CHECK(octet_length(base_manifest) BETWEEN 1 AND 2097152 AND jsonb_typeof(base_manifest::jsonb)='object'),
  base_manifest_digest char(64) NOT NULL CHECK(base_manifest_digest ~ '^[0-9a-f]{64}$' AND base_manifest_digest=encode(sha256(convert_to('pertexo.workflow.portable.manifest.v1','UTF8')||decode('00','hex')||convert_to(base_manifest,'UTF8')),'hex')),
  setup_targets jsonb NOT NULL CHECK(jsonb_typeof(setup_targets)='array' AND jsonb_array_length(setup_targets)<=16),
  supported_profile text NOT NULL CHECK(supported_profile='validate_activation'),
  selection_enabled boolean NOT NULL DEFAULT true,
  PRIMARY KEY(template_id,template_version)
);
ALTER TABLE app.curated_template_descriptors OWNER TO {{owner_role}};
REVOKE ALL ON app.curated_template_descriptors FROM PUBLIC,{{api_runtime_role}},
  {{worker_runtime_role}},{{dispatcher_role}},{{maintenance_role}},{{operator_role}},{{lifecycle_command_role}};
GRANT SELECT ON app.curated_template_descriptors TO {{api_runtime_role}};

