-- Installed content is immutable even for later owner selection changes.
CREATE FUNCTION app.guard_curated_template_descriptor() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$
BEGIN
  IF TG_OP='DELETE' OR (to_jsonb(NEW)-'selection_enabled') IS DISTINCT FROM (to_jsonb(OLD)-'selection_enabled') THEN
    RAISE EXCEPTION 'curated descriptor content is immutable' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;
ALTER FUNCTION app.guard_curated_template_descriptor() OWNER TO {{owner_role}};
REVOKE ALL ON FUNCTION app.guard_curated_template_descriptor() FROM PUBLIC;
CREATE TRIGGER curated_template_descriptor_immutable BEFORE UPDATE OR DELETE
  ON app.curated_template_descriptors FOR EACH ROW EXECUTE FUNCTION app.guard_curated_template_descriptor();

