  PRIMARY KEY(workspace_id,workflow_id),
  FOREIGN KEY(workspace_id,workflow_id) REFERENCES app.workflows(workspace_id,id) ON DELETE CASCADE
);
ALTER TABLE app.workflow_template_origins OWNER TO {{owner_role}};
ALTER TABLE app.workflow_template_origins ENABLE ROW LEVEL SECURITY;
